-- 004 FR-011/012/091: «atómica e idempotente ... misma clave y otra huella falla».
-- ADR-004 / decisión 22.7: «el servidor fija el mes de vigencia»; T015: política rota.
begin;
select no_plan();
select tests.create_user('11111111-1111-4111-8111-111111111111','sara@seed.test');
select tests.create_user('22222222-2222-4222-8222-222222222222','tomas@seed.test');
select tests.create_user('33333333-3333-4333-8333-333333333333','third@seed.test');
select tests.seed_couple('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222');
insert into juntia_data.budgets(id,group_id,category_id,created_by) values('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','market','11111111-1111-4111-8111-111111111111');
insert into juntia_data.budget_versions(budget_id,effective_month,limit_minor,changed_by) values('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',date_trunc('month',now() at time zone 'America/Bogota')::date,10000,'11111111-1111-4111-8111-111111111111');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}';
select lives_ok($$select public.create_budget('10000000-0000-4000-8000-000000000001','us','restaurants','26000000')$$,'crear presupuesto compartido');
select lives_ok($$select public.create_budget('10000000-0000-4000-8000-000000000001','us','restaurants','26000000')$$,'reintento de crear idempotente');
select throws_ok($$select public.create_budget('10000000-0000-4000-8000-000000000001','us','restaurants','27000000')$$,'JT008',null,'clave con otra intención');
select throws_ok($$select public.create_budget(gen_random_uuid()::text,'us','restaurants','26000000')$$,'JT219',null,'no duplica identidad');
select throws_ok($$select public.create_budget(gen_random_uuid()::text,'me','market','0')$$,'JT221',null,'cero no es activo');
select throws_ok($$select public.create_budget(gen_random_uuid()::text,'me','income','10000')$$,'JT221',null,'no presupuesto para income');
select throws_ok($$select public.create_budget(gen_random_uuid()::text,'me','market','101')$$,'JT221',null,'pesos enteros');
select throws_ok($$select public.create_budget(gen_random_uuid()::text,'me','market','99999999901')$$,'JT221',null,'límite máximo');
select lives_ok($$select public.update_budget('10000000-0000-4000-8000-000000000002','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'20000')$$,'editar con versión');
select lives_ok($$select public.update_budget('10000000-0000-4000-8000-000000000002','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'20000')$$,'reintento de editar');
select throws_ok($$select public.update_budget('10000000-0000-4000-8000-000000000002','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'30000')$$,'JT008',null,'edición misma clave otra huella');
select throws_ok($$select public.update_budget(gen_random_uuid()::text,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'30000')$$,'JT011',null,'versión vieja no sobrescribe');
select lives_ok($$select public.update_budget('10000000-0000-4000-8000-000000000003','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',2,null)$$,'desactivar conserva identidad e historial');
select is((select limit_minor from public.budget_months where context='us' and category_id='market' and month=date_trunc('month',now() at time zone 'America/Bogota')::date),null::text,'desactivado es null, no cero');
reset role;
select is((select count(*) from juntia_data.budget_versions where budget_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),3::bigint,'dos cambios más la versión inicial');
select is((select count(*) from juntia_data.idempotency_records where idempotency_key='10000000-0000-4000-8000-000000000001'),1::bigint,'una intención de creación');
select is((select count(*) from juntia_data.budget_versions where effective_month<>date_trunc('month',now() at time zone 'America/Bogota')::date),0::bigint,'vigencia fijada por el servidor');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}';
select throws_ok($$select public.create_budget(gen_random_uuid()::text,'us','market','10000')$$,'JT105',null,'tercera cuenta sin pareja');
select throws_ok($$select public.update_budget(gen_random_uuid()::text,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',3,'10000')$$,'JT218',null,'tercera cuenta no modifica presupuesto');
reset role;
alter policy budgets_insert on juntia_data.budgets with check(false);
set local role authenticated;
set local "request.jwt.claims"='{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}';
select throws_ok($$select public.create_budget('10000000-0000-4000-8000-000000000004','me','services','10000')$$,null,null,'política rota: crear no confirma');
reset role;
alter policy budgets_insert on juntia_data.budgets with check(created_by=(select auth.uid()) and (owner_user_id=(select auth.uid()) or juntia_private.is_couple_member(group_id)));
alter policy budgets_update on juntia_data.budgets using(false);
set local role authenticated;
select throws_ok($$select public.update_budget('10000000-0000-4000-8000-000000000005','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',3,'30000')$$,null,null,'política rota: row_count impide falso éxito');
reset role;
select is((select count(*) from juntia_data.idempotency_records where idempotency_key in ('10000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000005')),0::bigint,'fallo revierte también idempotencia');
select * from finish();
rollback;
